insert into foot_lessons (error, rule, source_ref, active, created_at) values ('M1 (Dixon-Coles sur les buts) surestime la probabilité du côté choisi d''environ 9 points quand on filtre sur la valeur attendue > 0 (58 % annoncé, 49 % observé, backtest 2023-2026)', 'Ne jamais calculer la valeur attendue avec un modèle non recalibré contre le marché ; un modèle candidat doit battre M0 en perte log hors échantillon avant d''être actif.', 'phase1', true, '2026-10-04T19:50:43.186596+00:00');
insert into foot_lessons (error, rule, source_ref, active, created_at) values ('Une précision élevée sur environ 300 sélections disparaît après correction pour 10 variantes testées', 'Toujours appliquer la correction de tests multiples (Bonferroni ou BH) au nombre de variantes essayées avant de parler d''avantage.', 'phase1', true, '2026-10-04T19:50:43.188329+00:00');
insert into foot_hypotheses (title, description, priority, status, experiment_key, created_at) values ('M3 sélection ''plus'' uniquement', 'Les sélections M3 rentables sont surtout des « plus 2,5 » : tester la restriction au côté plus, hors échantillon sur 2026-27 en direct.', 1, 'à tester', null, '2026-10-04T19:50:43.189605+00:00') on conflict (title) do nothing;
insert into foot_hypotheses (title, description, priority, status, experiment_key, created_at) values ('Recalibration isotone de M1 contre le marché', 'Recalibrer M1 (isotone sur l''historique) avant de l''utiliser dans M3/M4.', 2, 'à tester', null, '2026-10-04T19:50:43.190864+00:00') on conflict (title) do nothing;
insert into foot_hypotheses (title, description, priority, status, experiment_key, created_at) values ('xG 2026-27 dans M1', 'Mesurer l''apport des xG (disponibles depuis 2026-27) sur la perte log de M1 et M3.', 2, 'à tester', null, '2026-10-04T19:50:43.192138+00:00') on conflict (title) do nothing;
insert into foot_hypotheses (title, description, priority, status, experiment_key, created_at) values ('Mouvement de cote ouverture -> verrouillage', 'Utiliser l''évolution de la cote entre deux instantanés comme variable (exige des instantanés réguliers).', 3, 'à tester', null, '2026-10-04T19:50:43.193360+00:00') on conflict (title) do nothing;
insert into foot_hypotheses (title, description, priority, status, experiment_key, created_at) values ('Seuil de valeur optimal', 'Tester seuil_valeur 0 %, 2 %, 4 % pour M3 avec correction des tests multiples.', 3, 'à tester', null, '2026-10-04T19:50:43.194465+00:00') on conflict (title) do nothing;
insert into foot_hypotheses (title, description, priority, status, experiment_key, created_at) values ('Re-sélection à T-75 min', 'Variante d''observation : re-sélectionner avec les compositions confirmées (exige une source de compositions).', 4, 'à tester', null, '2026-10-04T19:50:43.195564+00:00') on conflict (title) do nothing;
